namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Instructor
{
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

public class Course
{
    public string Id { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Room { get; set; } = string.Empty;
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = string.Empty;
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics, from algebra to analysis." },
        new() { Id = "eng", Name = "English", Description = "Literature, composition, and creative writing." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "hist", Name = "History", Description = "Exploration of past events and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new()
        {
            Id = "CS101", Title = "Introduction to Programming", DepartmentId = "cs",
            Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Science Hall 201",
            Instructor = new() { Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen has 15 years of experience teaching introductory CS courses. She received her Ph.D. from MIT and specializes in CS education.", Email = "s.chen@university.edu" },
            IsFeatured = true
        },
        new()
        {
            Id = "CS301", Title = "Data Structures & Algorithms", DepartmentId = "cs",
            Description = "Advanced study of data organization and algorithm design. Topics include trees, graphs, sorting, searching, and complexity analysis.",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", Room = "Science Hall 305",
            Instructor = new() { Name = "Dr. James Park", Title = "Professor", Bio = "Dr. Park is a leading researcher in algorithm optimization with over 50 published papers. He joined the faculty in 2008.", Email = "j.park@university.edu" },
            IsFeatured = true
        },
        new()
        {
            Id = "CS420", Title = "Machine Learning", DepartmentId = "cs",
            Description = "Introduction to machine learning techniques including supervised learning, unsupervised learning, and neural networks. Prerequisites: CS301, MATH201.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", Room = "Tech Building 110",
            Instructor = new() { Name = "Dr. Amara Okafor", Title = "Assistant Professor", Bio = "Dr. Okafor completed her postdoc at Stanford AI Lab. Her research focuses on interpretable ML models.", Email = "a.okafor@university.edu" },
            IsFeatured = true
        },
        new()
        {
            Id = "MATH101", Title = "Calculus I", DepartmentId = "math",
            Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Math Building 101",
            Instructor = new() { Name = "Dr. Robert Liu", Title = "Professor", Bio = "Dr. Liu has taught calculus for over 20 years and authored two widely-used textbooks on the subject.", Email = "r.liu@university.edu" },
            IsFeatured = false
        },
        new()
        {
            Id = "MATH201", Title = "Linear Algebra", DepartmentId = "math",
            Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Room = "Math Building 203",
            Instructor = new() { Name = "Dr. Elena Volkov", Title = "Associate Professor", Bio = "Dr. Volkov specializes in applied linear algebra and has consulted for several tech companies on optimization problems.", Email = "e.volkov@university.edu" },
            IsFeatured = true
        },
        new()
        {
            Id = "ENG110", Title = "College Composition", DepartmentId = "eng",
            Description = "Develop effective writing skills through essays, research papers, and peer review. Focus on argumentation and clarity.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Humanities Hall 102",
            Instructor = new() { Name = "Prof. David Morrison", Title = "Senior Lecturer", Bio = "Prof. Morrison is an award-winning essayist who has taught writing at the university level for 12 years.", Email = "d.morrison@university.edu" },
            IsFeatured = false
        },
        new()
        {
            Id = "ENG250", Title = "American Literature", DepartmentId = "eng",
            Description = "Survey of American literary traditions from the colonial period to the present, including poetry, fiction, and nonfiction.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", Room = "Humanities Hall 210",
            Instructor = new() { Name = "Dr. Maria Santos", Title = "Professor", Bio = "Dr. Santos is a Pulitzer-nominated critic whose work focuses on 20th-century American fiction.", Email = "m.santos@university.edu" },
            IsFeatured = false
        },
        new()
        {
            Id = "PHYS101", Title = "General Physics I", DepartmentId = "phys",
            Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions. Co-requisite: MATH101.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", Room = "Physics Lab 100",
            Instructor = new() { Name = "Dr. Kevin O'Brien", Title = "Associate Professor", Bio = "Dr. O'Brien's research in experimental physics has been funded by NSF. He emphasizes hands-on learning.", Email = "k.obrien@university.edu" },
            IsFeatured = false
        },
        new()
        {
            Id = "HIST101", Title = "World History to 1500", DepartmentId = "hist",
            Description = "Survey of global civilizations from prehistory through the late medieval period. Examines political, social, and cultural developments.",
            Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", Room = "Liberal Arts 301",
            Instructor = new() { Name = "Dr. Patricia Nguyen", Title = "Professor", Bio = "Dr. Nguyen is a specialist in ancient and medieval Asian history with extensive fieldwork experience.", Email = "p.nguyen@university.edu" },
            IsFeatured = false
        },
        new()
        {
            Id = "HIST220", Title = "Modern European History", DepartmentId = "hist",
            Description = "Europe from the French Revolution to the present. Covers industrialization, world wars, decolonization, and the EU.",
            Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", Room = "Liberal Arts 205",
            Instructor = new() { Name = "Dr. Thomas Weber", Title = "Associate Professor", Bio = "Dr. Weber is a German-born historian specializing in 20th-century European political history.", Email = "t.weber@university.edu" },
            IsFeatured = true
        },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, string? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId == departmentId);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Id.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();
}

