@page "/enroll"

<PageTitle>Enrollment Request</PageTitle>

@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<h1>Enrollment Request</h1>
<p class="text-muted">Submit your enrollment request below. You will receive confirmation via your university email.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
            <strong>@CatalogService.GetCourse(Model.CourseId)?.Title</strong> has been received.</p>
        <hr />
        <p class="mb-0">You will receive a confirmation email at your university address within 2 business days.</p>
    </div>
    <a href="/enroll" class="btn btn-primary">Submit Another Request</a>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <form method="post" action="/enroll">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
                    @if (validationErrors.ContainsKey(nameof(Model.StudentName)))
                    {
                        <div class="text-danger">@validationErrors[nameof(Model.StudentName)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" placeholder="e.g., CS123456" required />
                    @if (validationErrors.ContainsKey(nameof(Model.StudentId)))
                    {
                        <div class="text-danger">@validationErrors[nameof(Model.StudentId)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select id="courseId" name="Model.CourseId" class="form-select" required>
                        <option value="">— Select a course —</option>
                        @foreach (var course in CatalogService.GetAllCourses())
                        {
                            <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Id — @course.Title (@course.Credits cr)</option>
                        }
                    </select>
                    @if (validationErrors.ContainsKey(nameof(Model.CourseId)))
                    {
                        <div class="text-danger">@validationErrors[nameof(Model.CourseId)]</div>
                    }
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                <a href="/courses" class="btn btn-link">Cancel</a>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    public UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "course")]
    public string? PreselectedCourse { get; set; }

    private bool Submitted { get; set; }
    private Dictionary<string, string> validationErrors = new();

    protected override void OnInitialized()
    {
        if (!string.IsNullOrEmpty(PreselectedCourse) && string.IsNullOrEmpty(Model.CourseId))
        {
            Model.CourseId = PreselectedCourse;
        }

        if (HttpContextAccessor is not null)
        {
            // Validate on POST
            var context = HttpContextAccessor.HttpContext;
            if (context?.Request.Method == "POST")
            {
                Validate();
            }
        }
    }

    [CascadingParameter]
    public HttpContext? HttpContextAccessor { get; set; }

    private void Validate()
    {
        validationErrors.Clear();
        var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var ctx = new System.ComponentModel.DataAnnotations.ValidationContext(Model);

        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(Model, ctx, results, true))
        {
            foreach (var result in results)
            {
                foreach (var member in result.MemberNames)
                {
                    validationErrors[member] = result.ErrorMessage ?? "Invalid";
                }
            }
        }
        else
        {
            Submitted = true;
        }
    }
}

